{
  "book_code": "TJOB",
  "verses": [
    {
      "chapter": 1,
      "verse": 21,
      "text_ar": "سيجلب لك العديد من الأوبئة الشديدة، ويسلب منك كل ما لديك."
    },
    {
      "chapter": 1,
      "verse": 22,
      "text_ar": "سيأخذ أطفالك، ويُلحق بك العديد من الشرور."
    },
    {
      "chapter": 1,
      "verse": 23,
      "text_ar": "ثم يجب أن تصارع كرياضي وتتحمل الألم، واثقًا من مكافأتك، وتغلب الاختبارات والابتلاءات."
    },
    {
      "chapter": 1,
      "verse": 24,
      "text_ar": "ولكن عندما تصبر، سأجعل اسمك مشهورًا عبر جميع أجيال الأرض حتى نهاية العالم."
    },
    {
      "chapter": 1,
      "verse": 25,
      "text_ar": "وسأعيد لك كل ما كنت تمتلكه، وسيُعطى لك ضعف ما ستفقده لتعلم أن الله لا يميز بين الناس بل يعطي لكل من يستحق الخير."
    }
  ]
}
